def reviewed_unixunix_makefile(root,expected):
    assert expected==EXPECTED_OLD,'Unexpected historical Makefile pin'
    root=Path(root);raw=(root/'nethack-c/wasm/tu-ports.json').read_bytes()
    current=(root/'.cache/wasm64-build/tree/src/Makefile').read_bytes();actual=hashlib.sha256(current).hexdigest()
    registry_actual=hashlib.sha256(raw).hexdigest()
    matches=[(name,p)for name,p in PROFILES.items()if p['registrySha256']==registry_actual and p['makefileSha256']==actual]
    assert len(matches)==1,'Unreviewed or ambiguous actual registry/Makefile pair; no automatic pin refresh'
    name,p=matches[0];rows=json.loads(raw)
    assert [(r['name'],r['source'])for r in rows]==p['orderedSourceProjection'],'Registry selector projection changed'
    assert actual==p['makefileSha256'],'Unreviewed actual Makefile bytes or rebuild separators'
    e=p['inverse'];a,b=e['start'],e['stop']
    assert current[a:b]==bytes.fromhex(e['oldHex']),'Exact inverse input span changed'
    restored=current[:a]+bytes.fromhex(e['newHex'])+current[b:]
    assert hashlib.sha256(restored).hexdigest()==EXPECTED_OLD,'Inverse failed historical pin'
    print('UNIXUNIX reviewed Makefile '+name+' actual '+actual+'; exact inverse to frozen110, changed game link selection, fresh CPP mandatory')
    return restored
